css:
.content.p38-page { --p38-pad-x: var(--s-3); --p38-pad-y: var(--s-3); padding: var(--p38-pad-y) var(--p38-pad-x); min-height: 100%; display: flex; flex-direction: column; gap: var(--s-4); }
@media (min-width: 48rem) and (min-height: 31.25rem) { .content.p38-page { --p38-pad-x: var(--s-5); --p38-pad-y: var(--s-4); } }
.p38-foot { position: sticky; bottom: 0; z-index: 1; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--s-2); margin: auto calc(var(--p38-pad-x) * -1) calc(var(--p38-pad-y) * -1); padding: var(--s-3) var(--p38-pad-x); background: var(--white); border-top: var(--w1) solid var(--rule); }
.p38-col { display: grid; gap: var(--s-4); width: 100%; max-width: 48rem; align-content: start; }
.p38-head { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-2) var(--s-3); }
.p38-titlerow { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--s-2) var(--s-3); width: 100%; }
.p38-state { display: flex; align-items: center; gap: var(--s-3); padding-block: var(--s-3); }
.p38-err { --frame-w: var(--w2); }
.p38-wrapbtn { flex-wrap: wrap; }
.p38-wrapbtn .banner__text { flex: 1 1 14rem; }
.input.p38-focus { border: var(--w2) solid var(--blue); padding-inline: calc(var(--s-3) - var(--w1)); }
.p38-note { display: grid; gap: var(--s-2); justify-items: start; }

.p38-create { }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p38-create { margin-inline-start: auto; } }
.p38-tipwrap { display: flex; }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p38-tipwrap { justify-content: flex-end; } }
.p38-list { display: grid; gap: var(--s-2); margin: 0; padding: 0; }
.p38-point { border: 0; width: 100%; text-align: start; color: var(--ink); font: inherit; cursor: pointer; appearance: none; }
.p38-point .rec__body > *, .p38-point .rec__value { display: block; }
.p38-point .rec__value { display: flex; justify-content: flex-end; align-items: center; }
.p38-point[aria-disabled="true"] { --frame-color: var(--c-disabled-border); cursor: not-allowed; }
.p38-point[aria-disabled="true"] .rec__title, .p38-point[aria-disabled="true"] .rec__value { color: var(--c-disabled-text); }
.p38-empty { padding: var(--s-4) var(--s-3); max-width: var(--measure); }
.p38-spin { display: flex; align-items: center; gap: var(--s-3); }
.p38-btnspin { display: inline-flex; }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p38-shift .p38-col { margin-top: calc(var(--p38-shift, 0rem) * -1); } }
